function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 2 || arr.length > 500) return 'arr needs 2 to 500 values.';
  if (arr.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Each value is an integer between -1000 and 1000.';
  return null;
}

