function generate(rand, size) {
  const n = size === 'large' ? 500 : 2 + Math.floor(rand() * 7);
  const mode = rand();
  const pick = () => {
    if (mode < 0.3) {
      // Only odd values: no value can be twice another.
      const odd = 2 * Math.floor(rand() * (size === 'large' ? 1000 : 8)) - (size === 'large' ? 999 : 7);
      return odd;
    }
    if (mode < 0.5 && size === 'large') {
      // Magnitudes above 500: doubling leaves the range.
      const magnitude = 501 + Math.floor(rand() * 500);
      return rand() < 0.5 ? magnitude : -magnitude;
    }
    const span = size === 'large' ? 1000 : 6;
    return Math.floor(rand() * (2 * span + 1)) - span;
  };
  return [Array.from({ length: n }, pick)];
}
